from pathlib import Path
import datetime, hashlib, json, os, plistlib, stat, subprocess, sys
HOST=__HOST_JSON__
def sha(data):return hashlib.sha256(data).hexdigest()
def bounded(path,limit=65536):
 with open(path,'rb') as stream:data=stream.read(limit+1)
 if len(data)>limit:raise ValueError('fixed read bound exceeded')
 return data
def version(value):
 return dict(device=value.st_dev,inode=value.st_ino,size=value.st_size,mode=oct(stat.S_IMODE(value.st_mode)),uid=value.st_uid,gid=value.st_gid,mtime_ns=str(value.st_mtime_ns),ctime_ns=str(value.st_ctime_ns))
identity=dict(system=os.uname().sysname,machine=os.uname().machine,effective_uid=os.geteuid())
if sys.platform=='darwin':
 run=subprocess.run(['/usr/sbin/ioreg','-rd1','-c','IOPlatformExpertDevice','-a'],capture_output=True,check=True,timeout=10)
 assert len(run.stdout)<=65536
 uuids=[value['IOPlatformUUID'] for value in plistlib.loads(run.stdout) if 'IOPlatformUUID' in value]
 assert len(uuids)==1
 identity['platform_uuid_sha256']=sha(uuids[0].strip().lower().encode('ascii'))
 identity['boot_session_uuid']=subprocess.run(['/usr/sbin/sysctl','-n','kern.bootsessionuuid'],capture_output=True,text=True,check=True,timeout=5).stdout.strip()
else:
 identity['machine_id_sha256']=sha(bounded('/etc/machine-id',256).strip().lower())
 identity['boot_id']=bounded('/proc/sys/kernel/random/boot_id',256).decode('ascii').strip()
results={}
for name in ('ida','idat64'):
 run=subprocess.run(['/bin/sh','-c','command -v '+name],capture_output=True,text=True,timeout=5)
 path=run.stdout.strip()
 row=dict(lookup='command -v',found=run.returncode==0 and bool(path))
 if row['found']:
  invocation=Path(path); original=invocation.lstat(); real=invocation.resolve(strict=True)
  row.update(path=str(invocation),realpath=str(real),invocation_kind='symlink' if stat.S_ISLNK(original.st_mode) else 'direct')
  fd=os.open(real,os.O_RDONLY|os.O_CLOEXEC|os.O_NOFOLLOW)
  try:
   before=os.fstat(fd);row['version']=version(before)
   if stat.S_ISREG(before.st_mode) and before.st_size<=512*1024*1024:
    digest=hashlib.sha256();total=0
    while True:
     block=os.read(fd,1024*1024)
     if not block:break
     total+=len(block);assert total<=512*1024*1024
     digest.update(block)
    after=os.fstat(fd)
    row['hash_stable']=version(before)==version(after) and total==before.st_size and invocation.resolve(strict=True)==real
    if row['hash_stable']:row['sha256']=digest.hexdigest()
   else:row['sha256_not_computed']='not a regular file or exceeds 512 MiB bound'
  finally:os.close(fd)
 results[name]=row
print(json.dumps(dict(schema='hepta.rea.provider-path-addendum-host.v1',configured_host=HOST,observed_at_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),identity=identity,path_commands=results,read_only=True,applications_launched=False,full_disk_search=False,software_installed=False,scope='two additional PATH names only; not-found is not global absence'),separators=(',',':')),flush=True)
